#include <bits/stdc++.h>
using namespace std;

long long computePower(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    cin >> N >> M >> L >> R;
    long long totalCells = N * M;
    long long rangeSize = R - L + 1;
    const long long mod = 998244353;
    long long answer;
    if (totalCells % 2 == 1) {
        answer = computePower(rangeSize, totalCells, mod);
    } else if (rangeSize % 2 == 0) {
        answer = (computePower(rangeSize, totalCells, mod) * (mod + 1) / 2) % mod;
    } else {
        answer = (((computePower(rangeSize, totalCells, mod) + 1) % mod) * (mod + 1) / 2) % mod;
    }
    cout << answer << "\n";
    return 0;
}
